-- Procedure dedup Phase 0 — one-time consolidation (generated by
-- scripts/diag/proc_consolidate.py --emit-sql; audit §6). Collapses the duplicate
-- clusters into one canonical each (archive-not-delete: active=false + superseded_by),
-- folding affinity + outcome counters and deleting incident graph edges. The loop-close
-- code (bootstrap/reactivate redirect on superseded_by, shipped in #488) is deployed
-- before this runs (run_migrations precedes bootstrap), so archived skill rows are not
-- re-imported at startup. No-op on DBs lacking these ids. Splitter-safe: no DO blocks,
-- no BEGIN/COMMIT (run_migrations wraps the file in one transaction).

-- ===== cluster: email =====
INSERT INTO heart.procedure_task_affinity (procedure_id, frame_type, activation_count, success_count, failure_count, last_activated_at, active, agent_id)
SELECT '54fedf18-1299-41ae-8ad8-e7a795f4f70a', s.frame_type, SUM(s.activation_count), SUM(s.success_count), SUM(s.failure_count), MAX(s.last_activated_at), bool_or(s.active), 'nous-default'
FROM heart.procedure_task_affinity s JOIN heart.procedures p ON p.id = s.procedure_id AND p.superseded_by IS NULL
WHERE s.agent_id = 'nous-default' AND s.procedure_id = ANY(ARRAY['47fbb706-7aff-4811-8136-8973f4894197','2a1f583b-d495-4a0e-9131-30d27dfc30c5','576e10f4-4a45-4e3b-a7aa-8efd962c588a','828da799-9890-4a52-b99a-87bed68731be','97cb7b96-41f2-400f-bef1-b6d1ae38f77f']::uuid[])
GROUP BY s.frame_type
ON CONFLICT (procedure_id, frame_type, agent_id) DO UPDATE SET activation_count = heart.procedure_task_affinity.activation_count + EXCLUDED.activation_count, success_count = heart.procedure_task_affinity.success_count + EXCLUDED.success_count, failure_count = heart.procedure_task_affinity.failure_count + EXCLUDED.failure_count, last_activated_at = GREATEST(heart.procedure_task_affinity.last_activated_at, EXCLUDED.last_activated_at), active = heart.procedure_task_affinity.active OR EXCLUDED.active;
DELETE FROM heart.procedure_task_affinity WHERE agent_id = 'nous-default' AND procedure_id = ANY(ARRAY['47fbb706-7aff-4811-8136-8973f4894197','2a1f583b-d495-4a0e-9131-30d27dfc30c5','576e10f4-4a45-4e3b-a7aa-8efd962c588a','828da799-9890-4a52-b99a-87bed68731be','97cb7b96-41f2-400f-bef1-b6d1ae38f77f']::uuid[]);
UPDATE heart.procedures c SET activation_count = coalesce(c.activation_count,0)+agg.act, success_count = coalesce(c.success_count,0)+agg.succ, failure_count = coalesce(c.failure_count,0)+agg.fail, neutral_count = coalesce(c.neutral_count,0)+agg.neu, updated_at = now() FROM (SELECT coalesce(sum(activation_count),0) act, coalesce(sum(success_count),0) succ, coalesce(sum(failure_count),0) fail, coalesce(sum(neutral_count),0) neu FROM heart.procedures s WHERE s.agent_id = 'nous-default' AND s.id = ANY(ARRAY['47fbb706-7aff-4811-8136-8973f4894197','2a1f583b-d495-4a0e-9131-30d27dfc30c5','576e10f4-4a45-4e3b-a7aa-8efd962c588a','828da799-9890-4a52-b99a-87bed68731be','97cb7b96-41f2-400f-bef1-b6d1ae38f77f']::uuid[]) AND s.superseded_by IS NULL) agg WHERE c.id = '54fedf18-1299-41ae-8ad8-e7a795f4f70a' AND c.agent_id = 'nous-default';
UPDATE heart.procedures SET implementation_notes = array_append(coalesce(implementation_notes, ARRAY[]::text[]), 'When email delivery must be audited: capture the SMTP response code, append the send to a persistent log file, and record the outcome as a fact (folded in from validated-email-sending on consolidation).'), updated_at = now() WHERE id = '54fedf18-1299-41ae-8ad8-e7a795f4f70a' AND agent_id = 'nous-default' AND NOT ('When email delivery must be audited: capture the SMTP response code, append the send to a persistent log file, and record the outcome as a fact (folded in from validated-email-sending on consolidation).' = ANY(coalesce(implementation_notes, ARRAY[]::text[])));
DELETE FROM brain.graph_edges WHERE agent_id = 'nous-default' AND ((source_id = ANY(ARRAY['47fbb706-7aff-4811-8136-8973f4894197','2a1f583b-d495-4a0e-9131-30d27dfc30c5','576e10f4-4a45-4e3b-a7aa-8efd962c588a','828da799-9890-4a52-b99a-87bed68731be','97cb7b96-41f2-400f-bef1-b6d1ae38f77f']::uuid[]) AND source_type = 'procedure') OR (target_id = ANY(ARRAY['47fbb706-7aff-4811-8136-8973f4894197','2a1f583b-d495-4a0e-9131-30d27dfc30c5','576e10f4-4a45-4e3b-a7aa-8efd962c588a','828da799-9890-4a52-b99a-87bed68731be','97cb7b96-41f2-400f-bef1-b6d1ae38f77f']::uuid[]) AND target_type = 'procedure'));
UPDATE heart.procedures SET active = false, archived_at = now(), superseded_by = '54fedf18-1299-41ae-8ad8-e7a795f4f70a' WHERE agent_id = 'nous-default' AND id = ANY(ARRAY['47fbb706-7aff-4811-8136-8973f4894197','2a1f583b-d495-4a0e-9131-30d27dfc30c5','576e10f4-4a45-4e3b-a7aa-8efd962c588a','828da799-9890-4a52-b99a-87bed68731be','97cb7b96-41f2-400f-bef1-b6d1ae38f77f']::uuid[]) AND superseded_by IS NULL;

-- ===== cluster: action_gate =====
INSERT INTO heart.procedure_task_affinity (procedure_id, frame_type, activation_count, success_count, failure_count, last_activated_at, active, agent_id)
SELECT 'a1cefc07-80cb-45cd-84ff-497564eab187', s.frame_type, SUM(s.activation_count), SUM(s.success_count), SUM(s.failure_count), MAX(s.last_activated_at), bool_or(s.active), 'nous-default'
FROM heart.procedure_task_affinity s JOIN heart.procedures p ON p.id = s.procedure_id AND p.superseded_by IS NULL
WHERE s.agent_id = 'nous-default' AND s.procedure_id = ANY(ARRAY['408d59db-3cb1-4eb3-be75-1cd7045dc1d4']::uuid[])
GROUP BY s.frame_type
ON CONFLICT (procedure_id, frame_type, agent_id) DO UPDATE SET activation_count = heart.procedure_task_affinity.activation_count + EXCLUDED.activation_count, success_count = heart.procedure_task_affinity.success_count + EXCLUDED.success_count, failure_count = heart.procedure_task_affinity.failure_count + EXCLUDED.failure_count, last_activated_at = GREATEST(heart.procedure_task_affinity.last_activated_at, EXCLUDED.last_activated_at), active = heart.procedure_task_affinity.active OR EXCLUDED.active;
DELETE FROM heart.procedure_task_affinity WHERE agent_id = 'nous-default' AND procedure_id = ANY(ARRAY['408d59db-3cb1-4eb3-be75-1cd7045dc1d4']::uuid[]);
UPDATE heart.procedures c SET activation_count = coalesce(c.activation_count,0)+agg.act, success_count = coalesce(c.success_count,0)+agg.succ, failure_count = coalesce(c.failure_count,0)+agg.fail, neutral_count = coalesce(c.neutral_count,0)+agg.neu, updated_at = now() FROM (SELECT coalesce(sum(activation_count),0) act, coalesce(sum(success_count),0) succ, coalesce(sum(failure_count),0) fail, coalesce(sum(neutral_count),0) neu FROM heart.procedures s WHERE s.agent_id = 'nous-default' AND s.id = ANY(ARRAY['408d59db-3cb1-4eb3-be75-1cd7045dc1d4']::uuid[]) AND s.superseded_by IS NULL) agg WHERE c.id = 'a1cefc07-80cb-45cd-84ff-497564eab187' AND c.agent_id = 'nous-default';
DELETE FROM brain.graph_edges WHERE agent_id = 'nous-default' AND ((source_id = ANY(ARRAY['408d59db-3cb1-4eb3-be75-1cd7045dc1d4']::uuid[]) AND source_type = 'procedure') OR (target_id = ANY(ARRAY['408d59db-3cb1-4eb3-be75-1cd7045dc1d4']::uuid[]) AND target_type = 'procedure'));
UPDATE heart.procedures SET active = false, archived_at = now(), superseded_by = 'a1cefc07-80cb-45cd-84ff-497564eab187' WHERE agent_id = 'nous-default' AND id = ANY(ARRAY['408d59db-3cb1-4eb3-be75-1cd7045dc1d4']::uuid[]) AND superseded_by IS NULL;

