UPDATE heart.procedures c SET activation_count = coalesce(c.activation_count,0)+agg.act, success_count = coalesce(c.success_count,0)+agg.succ, failure_count = coalesce(c.failure_count,0)+agg.fail, neutral_count = coalesce(c.neutral_count,0)+agg.neu, updated_at = now() FROM (SELECT coalesce(sum(activation_count),0) act, coalesce(sum(success_count),0) succ, coalesce(sum(failure_count),0) fail, coalesce(sum(neutral_count),0) neu FROM heart.procedures s WHERE s.agent_id = 'nous-default' AND s.id = ANY(ARRAY['656693fb-1319-4e92-89ee-0668246a4e1c']::uuid[]) AND s.superseded_by IS NULL) agg WHERE c.id = 'f045d70f-332e-4f14-b667-74aff68f7553' AND c.agent_id = 'nous-default';
