-- ===== backfill block-scalar-broken descriptions =====
UPDATE heart.procedures SET description = 'Conduct rigorous multi-source research: evaluate source credibility, triangulate claims across 3+ independent sources, separate established fact from speculation, and deliver structured reports with explicit confidence ratings.', updated_at = now() WHERE id = 'f6515b17-5a8a-4696-a425-3714dddcffdc' AND agent_id = 'nous-default' AND trim(description) = ANY(ARRAY['|','>','|-','>-','|+','>+']);
UPDATE heart.procedures SET description = 'Root-cause debugging: investigate errors, failures, and regressions to find the underlying cause before applying any fix — no symptom patching.', updated_at = now() WHERE id = '84a25199-a70f-4a26-a022-57f670e1feed' AND agent_id = 'nous-default' AND trim(description) = ANY(ARRAY['|','>','|-','>-','|+','>+']);
UPDATE heart.procedures SET description = 'Security audit and threat modeling: OWASP review, vulnerability and supply-chain scanning with confidence-gated findings (daily vs comprehensive scope modes).', updated_at = now() WHERE id = 'de9ff940-6e8c-4ffa-b292-3f519ca3ded2' AND agent_id = 'nous-default' AND trim(description) = ANY(ARRAY['|','>','|-','>-','|+','>+']);
UPDATE heart.procedures SET description = 'Brainstorming / product ''office hours'': think through whether and how to build an idea, choosing startup vs builder mode from the stated goal.', updated_at = now() WHERE id = '87dceb55-8d5d-406f-ae94-0103899ed2d3' AND agent_id = 'nous-default' AND trim(description) = ANY(ARRAY['|','>','|-','>-','|+','>+']);
